from pwn import *
import re
import ast
import string

def get_ciphertexts():
    r = remote('crypto.chal.csaw.io', 4141)
    r.recvuntil(b'Passwd')
    r.sendline(b'anything')
    data = r.recvall(timeout=2).decode()
    # Parse numeric array format
    c1_match = re.search(r'C1: (\[[^\]]+\])', data)
    c2_match = re.search(r'C2: (\[[^\]]+\])', data)
    if not c1_match or not c2_match:
        print('Could not find ciphertexts')
        exit()
    c1 = bytes(ast.literal_eval(c1_match.group(1)))
    c2 = bytes(ast.literal_eval(c2_match.group(1)))
    return c1, c2

def recover_flag_bytes(c1, c2, known_plaintext_bytes):
    xor_bytes = bytes([a ^ b for a, b in zip(c1, c2)])
    result = bytes([a ^ b for a, b in zip(xor_bytes, known_plaintext_bytes)])
    return result

def xor_remainder_flag_charset(c1, c2, prefix, start):
    allowed = b'FLAG{}_-' + string.ascii_letters.encode() + string.digits.encode()
    flag = bytearray(prefix)
    for i in range(start, len(c1)):
        next_xor = c1[i] ^ c2[i]
        # Choose printable ascii only
        candidates = [ch for ch in allowed if 32 <= (next_xor ^ ch) < 127]
        if b'}'[0] in candidates and len(flag) > 5:
            flag.append(next_xor ^ ord('}'))
            break
        elif candidates:
            flag.append(next_xor ^ candidates[0])
        else:
            flag.append(ord('?'))
    return bytes(flag)

