    c1, c2 = get_ciphertexts()
    msg1 = b'FAKE{LC5_I3_SH0RT}'
    guess = recover_flag_bytes(c1, c2, msg1)
    flag_guess = bytearray()
    for i, b in enumerate(guess):
        if 32 <= b < 127:
            flag_guess.append(b)
        else:
            break
    if not flag_guess.endswith(b'}') and len(flag_guess) < len(c1):
        flag_guess_extended = xor_remainder_flag_charset(c1, c2, flag_guess, len(flag_guess))
    else:
        flag_guess_extended = flag_guess
    print('Guessed flag:', flag_guess_extended.decode(errors='replace'))
    m = re.search(r'(FLAG\{[A-Za-z0-9_\-]*\})', flag_guess_extended.decode(errors='replace'))
    if m:
        print('FLAG match:', m.group(1))
    else:
        print('NO strict match found! Guessed:', flag_guess_extended)

if __name__ == '__main__':
    main()

